public int balancedParenthesis(String A) {
    char[] array = A.toCharArray();
    int N = array.length;
    if ((N & 1) != 0) {
        return 0;
    }
    Stack<Character> stack = new Stack<>();
    for (char target : array) {
        if (isForwardParenthesis(target)) {
            stack.push(target);
        } else {
            if (!stack.isEmpty()) {
                char topElement = stack.pop();
                char pairRequired = pairingParenthesis(target);
                if (topElement != pairRequired) {
                    return 0;
                }
            } else {
                return 0;
            }
        }
    }
    return stack.isEmpty() ? 1 : 0;
}

private boolean isForwardParenthesis(char x) {
    return x == '{' || x == '[' || x == '(';
}

private char pairingParenthesis(char x) {
    switch (x) {
        case '}': return '{';
        case ']': return '[';
        default: return '(';
    }
}

Stack<Integer> stack;
Stack<Integer> minStack;

public void minStackInit() {
    stack = new Stack<>();
    minStack = new Stack<>();
}

public void push(int val) {
    stack.push(val);
    if (!minStack.isEmpty()) {
        minStack.push(Math.min(val, minStack.peek()));
    } else {
        minStack.push(val);
    }
}

public void pop() {
    if (!stack.isEmpty()) {
        stack.pop();
        minStack.pop();
    }
}

public int top() {
    if (!stack.isEmpty()) {
        return stack.peek();
    }
    return -1;
}

public int getMin() {
    if (!stack.isEmpty()) {
        return minStack.peek();
    }
    return -1;
}

