public int redundantBracesUnecessaryBraces(String A) {
    char[] charArray = A.toCharArray();
    Stack<Character> stack = new Stack<>();
    for (char x : charArray) {
        if (x == ')') {
            boolean hasOp = false;
            while (stack.peek() != '(') {
                hasOp = hasOp || isOperator(stack.peek());
                stack.pop();
            }
            stack.pop(); // remove '('
            if (!hasOp) {
                return 1;
            }
        } else {
            stack.push(x);
        }
    }
    return 0;
}

private boolean isOperator(char token) {
    return token == '+' || token == '-' || token == '*' || token == '/';
}

public int largestRectangleInAHistogram(int[] A) {
    int N = A.length;
    int maxArea = -1;
    int[] prevSmallerElements = nearestSmallerElementsToTheLeft(A);
    int[] nextSmallerElements = nearestSmallerElementsToTheRight(A);
    for (int i = 0; i < N; i++) {
        int height = A[i];
        int width = nextSmallerElements[i] - prevSmallerElements[i] - 1;
        int area = height * width;
        maxArea = Math.max(area, maxArea);
    }
    return maxArea;
}

public int[] nearestSmallerElementsToTheLeft(int[] A) {
    int N = A.length;
    Stack<Integer> stack = new Stack<>();
    int[] res = new int[N];
    res[0] = -1;
    stack.push(0);
    for (int i = 1; i < N; i++) {
        while (A[stack.peek()] >= A[i]) {
            stack.pop();
            if (stack.isEmpty()) {
                res[i] = -1;
                break;
            }
        }
        if (!stack.isEmpty()) {
            res[i] = stack.peek();
        }
        stack.push(i);
    }
    return res;
}

public int[] nearestSmallerElementsToTheRight(int[] A) {
    int N = A.length;
    Stack<Integer> stack = new Stack<>();
    int[] res = new int[N];
    for (int i = N - 1; i >= 0; i--) {
        while (!stack.isEmpty() && A[stack.peek()] >= A[i]) {
            stack.pop();
        }
        res[i] = stack.isEmpty() ? N : stack.peek();
        stack.push(i);
    }
    return res;
}

public int[] prevSmallerValuesInAnArray(int[] A) {
