public String doubleCharacterTrouble(String A) {
    Stack<Character> stack = new Stack<>();
    char[] array = A.toCharArray();
    for (char currentElement : array) {
        if (stack.isEmpty()) {
            stack.push(currentElement);
        } else {
            char prevElement = stack.peek();
            if (prevElement == currentElement) {
                stack.pop();
            } else {
                stack.push(currentElement);
            }
        }
    }
    StringBuilder result = new StringBuilder();
    while (!stack.isEmpty()) {
        result.insert(0, stack.pop());
    }
    return result.toString();
}

public int passingGameOfBall(int A, int B, int[] C) {
    Stack<Integer> stack = new Stack<>();
    stack.push(B);
    int currentPlayer = B;
    for (int i = 0; i < A; i++) {
        if (C[i] == 0) {
            stack.pop();
            currentPlayer = stack.peek();
        } else {
            currentPlayer = C[i];
            stack.push(C[i]);
        }
    }
    return currentPlayer;
}

public int checkTwoBracketExpressions(String A, String B) {
