public int[] build(String X) {
    int[] sign = new int[26];
    Stack<Integer> stack = new Stack<>();
    int currentSign = 1;
    stack.push(1);
    for (char c : X.toCharArray()) {
        if (c == '+') {
            currentSign = 1;
        } else if (c == '-') {
            currentSign = -1;
        } else if (c == '(') {
            stack.push(stack.peek() * currentSign);
            currentSign = 1;
        } else if (c == ')') {
            stack.pop();
        } else {
            sign[c - 'a'] = stack.peek() * currentSign;
        }
    }
    return sign;
}

