public String infixToPostfix(String A) {
    StringBuilder postfix = new StringBuilder();
    Stack<Character> stk = new Stack<>();
    for (char c : A.toCharArray()) {
        if (Character.isLetterOrDigit(c)) {
            postfix.append(c);
        } else if (c == '(') {
            stk.push(c);
        } else if (c == ')') {
            while (!stk.isEmpty() && stk.peek() != '(') {
                postfix.append(stk.pop());
            }
            stk.pop();
        } else {
            while (!stk.isEmpty() && stk.peek() != '(' && precedence(stk.peek()) >= precedence(c)) {
                postfix.append(stk.pop());
            }
            stk.push(c);
        }
    }
    while (!stk.isEmpty()) {
        postfix.append(stk.pop());
    }
    return postfix.toString();
}

private int precedence(char c) {
    switch (c) {
        case '^': return 3;
        case '*':
        case '/': return 2;
        case '+':
        case '-': return 1;
        default: return 0;
    }
}

public int maxAndMin(int[] A) {
    int N = A.length;
    int[] prevSmaller = new int[N];
    int[] prevGreater = new int[N];
    int[] nextSmaller = new int[N];
    int[] nextGreater = new int[N];
    Stack<Integer> stack = new Stack<>();
    stack.push(0);
    prevSmaller[0] = -1;
    for (int i = 1; i < N; i++) {
        while (A[stack.peek()] >= A[i]) {
            stack.pop();
            if (stack.isEmpty()) {
                prevSmaller[i] = -1;
                break;
            }
        }
        if (!stack.isEmpty()) {
            prevSmaller[i] = stack.peek();
        }
        stack.push(i);
    }
    stack = new Stack<>();
    stack.push(0);
    prevGreater[0] = -1;
    for (int i = 1; i < N; i++) {
        while (A[stack.peek()] <= A[i]) {
            stack.pop();
            if (stack.isEmpty()) {
                prevGreater[i] = -1;
                break;
            }
        }
        if (!stack.isEmpty()) {
            prevGreater[i] = stack.peek();
        }
        stack.push(i);
    }
    stack = new Stack<>();
    stack.push(N - 1);
    nextSmaller[N - 1] = N;
    for (int i = N - 2; i >= 0; i--) {
        while (A[stack.peek()] > A[i]) {
            stack.pop();
            if (stack.isEmpty()) {
                nextSmaller[i] = N;
                break;
            }
        }
        if (!stack.isEmpty()) {
            nextSmaller[i] = stack.peek();
        }
        stack.push(i);
    }
    stack = new Stack<>();
    stack.push(N - 1);
    nextGreater[N - 1] = N;
    for (int i = N - 2; i >= 0; i--) {
        while (A[stack.peek()] < A[i]) {
            stack.pop();
            if (stack.isEmpty()) {
                nextGreater[i] = N;
                break;
            }
        }
        if (!stack.isEmpty()) {
            nextGreater[i] = stack.peek();
        }
        stack.push(i);
    }
    long sum = 0;
    long MOD = 1000000007;
    for (int i = 0; i < N; i++) {
        long positive = (long) (i - prevGreater[i]) * (nextGreater[i] - i);
        sum += (positive * A[i]) % MOD;
        long negative = (long) (i - prevSmaller[i]) * (nextSmaller[i] - i);
        sum -= (negative * A[i]) % MOD;
        sum = (sum % MOD + MOD) % MOD;
    }
    return (int) sum;
}

