public int maxRectangleInBinaryMatrix(int[][] A) {
    int N = A.length;
    int M = A[0].length;
    int[] height = new int[M];
    int maxArea = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            if (A[i][j] == 1) {
                height[j]++;
            } else {
                height[j] = 0;
            }
        }
        int currentArea = largestRectangleInHistogram(height);
        maxArea = Math.max(maxArea, currentArea);
    }
    return maxArea;
}

private int largestRectangleInHistogram(int[] heights) {
    int N = heights.length;
    int maxArea = 0;
    int[] prevSmaller = new int[N];
    int[] nextSmaller = new int[N];
    Stack<Integer> stack = new Stack<>();
    prevSmaller[0] = -1;
    stack.push(0);
    for (int i = 1; i < N; i++) {
        while (heights[stack.peek()] >= heights[i]) {
            stack.pop();
            if (stack.isEmpty()) {
                prevSmaller[i] = -1;
                break;
            }
        }
        if (!stack.isEmpty()) {
            prevSmaller[i] = stack.peek();
        }
        stack.push(i);
    }
    stack = new Stack<>();
    nextSmaller[N - 1] = N;
    stack.push(N - 1);
    for (int i = N - 2; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        nextSmaller[i] = stack.isEmpty() ? N : stack.peek();
        stack.push(i);
    }
    for (int i = 0; i < N; i++) {
        int width = nextSmaller[i] - prevSmaller[i] - 1;
        int area = heights[i] * width;
        maxArea = Math.max(area, maxArea);
    }
    return maxArea;
}

public int[] nextGreaterValues(int[] A) {
    int N = A.length;
    int[] res = new int[N];
    Stack<Integer> stack = new Stack<>();
    stack.push(A[N - 1]);
    res[N - 1] = -1;
    for (int i = N - 2; i >= 0; i--) {
        while (stack.peek() <= A[i]) {
            stack.pop();
            if (stack.isEmpty()) {
                res[i] = -1;
                break;
            }
        }
        if (!stack.isEmpty()) {
            res[i] = stack.peek();
        }
        stack.push(A[i]);
    }
    return res;
}

