public int[] sortStackUsingAnotherStack(int[] A) {
    int N = A.length;
    Stack<Integer> stack = new Stack<>();
    Stack<Integer> sorted = new Stack<>();
    for (int x : A) {
        stack.push(x);
    }
    while (!stack.isEmpty()) {
        int x = stack.pop();
        if (sorted.isEmpty()) {
            sorted.push(x);
        } else if (sorted.peek() <= x) {
            sorted.push(x);
        } else {
            int count = 0;
            while (!sorted.isEmpty() && sorted.peek() >= x) {
                count++;
                stack.push(sorted.pop());
            }
            sorted.push(x);
            while (count != 0) {
                sorted.push(stack.pop());
                count--;
            }
        }
    }
    int[] ans = new int[N];
    for (int i = N - 1; i >= 0; i--) {
        ans[i] = sorted.pop();
    }
    return ans;
}
